import { revalidateTag } from 'next/cache'
import { getAllProducts } from '@/lib/db'

export default async function Page() {
  async function syncLatestCatalog() {
    'use server'
    // Mark every catalog view stale and refresh in the background.
    // Do not expire immediately: a full SKU sync must not block the admin UI.
    revalidateTag('products', 'max')
  }

  const products = await getAllProducts()

  return (
    <main>
      <h1>Product catalog</h1>
      <p>
        Day-to-day browsing uses the cached catalog. Sync when ERP or PIM data
        changes; the list may stay briefly stale while it refreshes.
      </p>
      <form action={syncLatestCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>
      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} — ${product.price}
          </li>
        ))}
      </ul>
    </main>
  )
}

